from taf.transport.ssh import ssh
from taf.rfrl.procedures.resources.python.logger.logger import log_input_and_output


class TestPC:
    """
    Responsible for handling remote commands execution on TestPC
    """
    def __init__(self, hostname, username, password, alias):
        self._session = ssh()
        self._session.connect_to(hostname=hostname,
                                 username=username,
                                 password=password,
                                 alias=alias)
        self._alias = alias

    @log_input_and_output
    def execute_command_and_get_output(self, command, timeout=60):
        """
        Executes provided command on remote and returns output.
        :param command: command to be executed on remote
        :type command: str
        :return: output of executed command on remote
        :rtype: str
        :param timeout: time in seconds for command to be executed; defaults to 60s
        :type timeout: int
        """
        return self._session.execute(command=command, connection=self._alias, timeout=timeout)

    @log_input_and_output
    def execute_command(self, command, timeout=60):
        """
        Executes provided command on remote.
        :param command: command to be executed on remote
        :type command: str
        :param timeout: time in seconds for command to be executed; defaults to 60s
        :type timeout: int
        """
        self._session.send_command(command=command, connection=self._alias)
        self._session.await_execution_end(connection=self._alias, timeout=timeout)

    @log_input_and_output
    def download_file(self, remote_path, local_path, timeout=60):
        """
         Download file from remote to local.
         :param remote_path: remote path with filename (and it's extension) to download, e.g. /remote/kappa.zip
         :type remote_path: str
         :param local_path: local path with filename (and it's extension) under which downloaded file will be saved,
                            e.g. /local/kappa.zip
         :type local_path: str
         :param timeout: time in seconds for command to be executed; defaults to 60s
         :type timeout: int
         """
        self._session.download_file(remote_path=remote_path, local_path=local_path, connection=self._alias)
        self._session.await_execution_end(connection=self._alias, timeout=timeout)
